/// True if `tag` appears in the loaded FIX spec dictionary.
/// O(1) bitmap lookup; intended as app-layer whitelist on untrusted feeds.
[[nodiscard]] inline constexpr bool is_known_tag(int tag) noexcept {
    unsigned const u = static_cast<unsigned>(tag);
    if (u > static_cast<unsigned>(detail::known_tag_max)) return false;
    return (detail::known_tag_bitmap[u >> 6] >> (u & 63u)) & 1u;
}

